import{_ as t,o as a,c as i,a1 as s}from"./chunks/framework.CiMD_7j0.js";const m=JSON.parse('{"title":"Platform Overview","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"5ec07dc1-36ff-4beb-812d-0aa792e73f45","PropagateID":"5ec07dc1-36ff-4beb-812d-0aa792e73f45","ReservedCode1":"7479a9fd-b7a9-45f1-a574-655764f03e7f","ReservedCode2":"7479a9fd-b7a9-45f1-a574-655764f03e7f"}},"headers":[],"relativePath":"en/guide/go/overview.md","filePath":"en/guide/go/overview.md","lastUpdated":null}'),n={name:"en/guide/go/overview.md"};function r(o,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="platform-overview" tabindex="-1">Platform Overview <a class="header-anchor" href="#platform-overview" aria-label="Permalink to &quot;Platform Overview&quot;">​</a></h1><p>ApeAdmin-Gin is the Go implementation of ApeAdmin: the backend is built on Gin v1.12 + GORM v1.31, config via Viper v1.21, logs via Zap v1.28, and the frontend uses Vue 3.5 + TypeScript + Vite + Element Plus. Business capabilities are extended via plugins; the core only handles authentication, permissions, menus, logging, data access and AI capabilities.</p><h2 id="what-it-solves" tabindex="-1">What It Solves <a class="header-anchor" href="#what-it-solves" aria-label="Permalink to &quot;What It Solves&quot;">​</a></h2><ul><li>Unified users, roles, menus and API permissions to support admin business scenarios.</li><li>A three-tier plugin system (compiled-in / declarative ZIP / external process) isolates business code with runtime enable/disable.</li><li>The MCP gateway safely exposes authorizable admin capabilities to AI agents.</li><li>Structured logs, request tracing and operation logs reduce troubleshooting cost.</li></ul><h2 id="runtime-boundary" tabindex="-1">Runtime Boundary <a class="header-anchor" href="#runtime-boundary" aria-label="Permalink to &quot;Runtime Boundary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser</span></span>
<span class="line"><span>  ├─ Vue Admin Panel (/)</span></span>
<span class="line"><span>  └─ Apehub_web Website (/apehub-web)</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          └─ Gin (/api/v1)</span></span>
<span class="line"><span>               ├─ Core APIs: auth / user / role / menu / dept / plugin</span></span>
<span class="line"><span>               ├─ MCP: tools / resources / prompts / audit-logs</span></span>
<span class="line"><span>               └─ Plugin APIs: mounted by the plugin itself</span></span></code></pre></div><p>Default port is 8001, default account admin / admin123. Config file <code>configs/config.yaml</code>, entry point <code>cmd/server/main.go</code>.</p><h2 id="directory-map" tabindex="-1">Directory Map <a class="header-anchor" href="#directory-map" aria-label="Permalink to &quot;Directory Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>cmd/server</code></td><td>Program entry: flag parsing + bootstrap.Run</td></tr><tr><td><code>configs</code></td><td>Global config (config.yaml)</td></tr><tr><td><code>internal/bootstrap</code></td><td>Startup orchestration: config → log → DB → seed → plugins → routes → graceful shutdown</td></tr><tr><td><code>internal/api</code></td><td>HTTP routes + handlers (public/auth/permission tiers)</td></tr><tr><td><code>internal/config</code></td><td>Viper config structs</td></tr><tr><td><code>internal/core</code></td><td>Core components: db / jwt / tokenstore / auditqueue / logger / seed / container</td></tr><tr><td><code>internal/middleware</code></td><td>Middleware chain: jwt_auth / login_guard / permission / rate_limit etc.</td></tr><tr><td><code>internal/model</code></td><td>GORM models (sys_ prefix)</td></tr><tr><td><code>internal/schema</code></td><td>Request/response DTOs</td></tr><tr><td><code>internal/dal</code></td><td>Data access layer</td></tr><tr><td><code>internal/service</code></td><td>Business logic layer</td></tr><tr><td><code>internal/mcp</code></td><td>MCP protocol system (manager / builtin)</td></tr><tr><td><code>internal/plugin</code></td><td>Plugin system (interface / registry / manager / eventbus / loader_l2 / zipguard)</td></tr><tr><td><code>internal/pkg</code></td><td>Shared utilities (response / pagination / tree / utils)</td></tr></tbody></table><h2 id="key-principles" tabindex="-1">Key Principles <a class="header-anchor" href="#key-principles" aria-label="Permalink to &quot;Key Principles&quot;">​</a></h2><ol><li>Core capabilities live in <code>internal/</code>; business capabilities live in plugin directories.</li><li>Plugin menus, APIs, tables and static assets must use their own namespaces.</li><li>Page permissions only improve the frontend experience; backend APIs must re-check permissions.</li><li>Production must change <code>jwt.secret</code>, otherwise the key-circuit-breaker refuses to start.</li></ol>`,11)])])}const h=t(n,[["render",r]]);export{m as __pageData,h as default};
